3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	
6	/**
7	 * Runs in the create-owner pipeline after {@link AssignCustomerCode} and
8	 * {@link DefaultOwnerRegistrationDate}, before {@link SaveOwner}. Assigns the owner's
9	 * {@code membershipNumber}, formatted {@code '<customerCode>-M<YY>'} where YY is the last two digits
10	 * of the fiscal year (starting 1 July) derived from the business-day-adjusted registrationDate, over
11	 * the region-and-hash customerCode (e.g. 'NSW-1A2B3C4D-M27'). The YY matches the owner's
12	 * {@link Owner#getFiscalYear() fiscalYear}. Mutates the built owner in place so later steps store and
13	 * respond with the assigned number.
14	 */
15	public class AssignMembershipNumber {
16	
17	    public void service(@Val Owner owner) {
18	        String yy = String.format("%02d", Owner.fiscalYearOf(owner.getRegistrationDate()) % 100);
19	        owner.setMembershipNumber(owner.getCustomerCode() + "-M" + yy);
20	    }
21	}
