1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Out;
4	import net.officefloor.plugin.variable.Val;
5	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
6	
7	/**
8	 * Runs in the create-owner pipeline before {@link BuildOwner}. Computes the deterministic
9	 * {@code householdId} — the first 12 hex characters of SHA-256 over the owner's normalized lastName
10	 * and postcode (see {@link HouseholdId#compute}) — and publishes it as an {@link Out} so
11	 * {@link AssignHousehold} can stamp it onto the owner being created (and {@link AssignHouseholdSize}
12	 * can size the household).
13	 *
14	 * <p>Because the identifier is derived from {@code (lastName, postcode)}, owners with the same
15	 * lastName and postcode share it automatically — no owner has to opt in. The {@code householdId} is
16	 * no longer part of the {@code identityKey}, so it no longer drives duplicate detection. An owner
17	 * with no postcode has no shared household, so {@code null} is published.
18	 */
19	public class DeriveHouseholdId {
20	
21	    public void service(@Val OwnerFieldsDto request, Out<HouseholdId> householdIdOut) {
22	        String householdId = HouseholdId.compute(request.getLastName(), request.getPostcode());
23	        householdIdOut.set(householdId == null ? null : new HouseholdId(householdId));
24	    }
25	}
