1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	
7	/**
8	 * Pipeline variable carrying the deterministic shared household identifier from
9	 * {@link DeriveHouseholdId} to {@link EnsureUniqueIdentity} and {@link AssignHousehold}. A dedicated
10	 * type (rather than a raw {@code String}) keeps the OfficeFloor by-type variable matching
11	 * unambiguous without a qualifier.
12	 *
13	 * <p>The identifier is <em>computed</em>, not allocated: {@link #compute} derives it from the
14	 * owner's normalized lastName and postcode, so owners with the same lastName and postcode share it
15	 * automatically without any owner opting in.
16	 */
17	public final class HouseholdId {
18	
19	    private final String value;
20	
21	    public HouseholdId(String value) {
22	        this.value = value;
23	    }
24	
25	    public String value() {
26	        return this.value;
27	    }
28	
29	    /**
30	     * The deterministic household identifier: the first 12 hex characters of SHA-256 over
31	     * {@code normalizedLastName + '|' + postcode}. Owners with the same lastName and postcode
32	     * therefore always share it.
33	     *
34	     * <p>A household is keyed on {@code (lastName, postcode)}, so without a postcode there is no
35	     * shared household: an absent or blank postcode yields {@code null} (a household of one).
36	     */
37	    public static String compute(String lastName, String postcode) {
38	        if (postcode == null || postcode.isBlank()) {
39	            return null;
40	        }
41	        String seed = normalizeLastName(lastName) + "|" + postcode.trim();
42	        return sha256Hex12(seed);
43	    }
44	
45	    /** Trim, collapse internal whitespace runs to a single space and lower-case. */
46	    private static String normalizeLastName(String value) {
47	        if (value == null) {
48	            return "";
49	        }
50	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
51	    }
52	
53	    /** The first 12 hex characters of SHA-256 over {@code seed}. */
54	    private static String sha256Hex12(String seed) {
55	        try {
56	            MessageDigest digest = MessageDigest.getInstance("SHA-256");
57	            byte[] hash = digest.digest(seed.getBytes(StandardCharsets.UTF_8));
58	            StringBuilder hex = new StringBuilder(12);
59	            for (int i = 0; hex.length() < 12; i++) {
60	                hex.append(String.format("%02x", hash[i] & 0xff));
61	            }
62	            return hex.substring(0, 12);
63	        } catch (NoSuchAlgorithmException e) {
64	            throw new IllegalStateException("SHA-256 not available", e); // every JRE ships SHA-256
65	        }
66	    }
67	}
