1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;
8	
9	/**
10	 * The single duplicate-detection step in the create-owner pipeline. Runs after the telephone and
11	 * email are normalized and after the disposable-email-domain blocklist has been applied.
12	 *
13	 * <p>Duplicate detection is expressed through the one {@code identityKey} — the SHA-256 hex of
14	 * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}, derived exactly as
15	 * {@link Owner#getIdentityKey()} does. A create whose whole key equals a stored owner's is rejected
16	 * with 409; soft-deleted owners are ignored. Because the telephone is part of the key, two owners
17	 * with the same lastName and postcode but different telephones have different keys and are not a
18	 * duplicate here — they are admitted and flagged as a soft match by {@link DetectPossibleDuplicate}.
19	 * The former separate household-duplicate 409 (from the computed {@code householdId}) no longer
20	 * applies.
21	 */
22	public class EnsureUniqueIdentity {
23	
24	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
25	            throws DuplicateIdentityException {
26	        String identityKey = Owner.identityKey(request.getTelephone(), request.getEmail(),
27	                request.getLastName());
28	        for (Owner existing : ownerRepository.findAll()) {
29	            if (Boolean.TRUE.equals(existing.getDeleted())) {
30	                continue; // soft-deleted owners no longer block a create
31	            }
32	            if (identityKey.equals(existing.getIdentityKey())) {
33	                throw new DuplicateIdentityException(identityKey);
34	            }
35	        }
36	    }
37	}
