289	    /**
290	     * The owner's salutation, derived at read time as the {@link #getTitle() title}, a single space
291	     * and the {@link #getLastName() lastName} (e.g. {@code 'DR Franklin'}); just the lastName when no
292	     * title is present.
293	     */
294	    @Transient
295	    public String getSalutation() {
296	        if (this.title == null || this.title.isBlank()) {
297	            return this.getLastName();
298	        }
299	        return this.title + " " + this.getLastName();
300	    }
301	
302	    /**
303	     * The canonical relative URL of this owner, derived at read time as {@code '/api/owners/'}
304	     * followed by the owner's {@link #getId() id}.
305	     */
306	    @Transient
307	    public String getSelfLink() {
308	        return "/api/owners/" + this.getId();
309	    }
310	
311	    /**
312	     * The fiscal year (starting 1 July) containing {@code date}, named by the calendar year it ends
313	     * in: a date on or after 1 July belongs to the next calendar year's fiscal year (e.g. 14 Aug
314	     * 2026 is fiscal year 2027), a date before 1 July to the current calendar year's.
315	     */
316	    public static int fiscalYearOf(LocalDate date) {
317	        return date.getMonthValue() >= 7 ? date.getYear() + 1 : date.getYear();
318	    }
319	
320	    /**
321	     * The owner's fiscal year, derived at read time from the business-day-adjusted
322	     * {@link #getRegistrationDate() registrationDate} and formatted {@code 'FY<YY>'} where YY is the
323	     * last two digits of the fiscal year (which starts on 1 July; e.g. a registration date of
324	     * 14 Aug 2026 yields {@code 'FY27'}). {@code null} when the owner has no registrationDate.
325	     */
326	    @Transient
327	    public String getFiscalYear() {
328	        if (this.registrationDate == null) {
329	            return null;
330	        }
331	        return String.format("FY%02d", fiscalYearOf(this.registrationDate) % 100);
332	    }
333	
334	    /**
335	     * The owner's membership points, derived at read time from stored fields. Starts at 0; add 2 when
336	     * an email is present; add 1 when {@link #getNamesakeCount() namesakeCount} is 0; add 2 for a
337	     * household of 3 or more ({@link #getHouseholdSize() householdSize}); add 3 when tenure — the
338	     * number of elapsed fiscal years since {@link #getRegistrationDate() registrationDate}
339	     * ({@link #getFiscalYear() fiscal year} basis, 1 July start) — is one or more. A newly created
340	     * owner has zero elapsed fiscal years of tenure, so a new owner can score at most 5 points.
341	     */
342	    @Transient
343	    public Integer getMembershipPoints() {
344	        return computeMembershipPoints(this.householdSize);
345	    }
346	
347	    private int computeMembershipPoints(Integer householdSize) {
348	        int points = 0;
349	        boolean hasEmail = this.email != null && !this.email.isBlank();
350	        if (hasEmail) {
351	            points += 2;
352	        }
353	        if (this.namesakeCount != null && this.namesakeCount == 0) {
354	            points += 1;
355	        }
356	        if (householdSize != null && householdSize >= 3) {
357	            points += 2;
358	        }
359	        if (this.registrationDate != null
360	                && fiscalYearOf(LocalDate.now()) - fiscalYearOf(this.registrationDate) >= 1) {
361	            points += 3;
362	        }
363	        return points;
364	    }
365	
366	    /**
367	     * The owner's membership level, a number from 1 to 4 derived at read time by banding
368	     * {@link #getMembershipPoints() membershipPoints}: 1 (0-1 points), 2 (2-3), 3 (4-5), 4 (6 or more).
