7	/**
8	 * Runs after {@link ValidateOwnerFields} and before {@link BuildOwner} in the create-owner
9	 * pipeline. Normalizes the telephone into E.164 form and mutates the validated body in place so
10	 * later steps build, compare and store the normalized value.
11	 *
12	 * <p>Rules: strip spaces, dashes and brackets. A leading {@code '+'} keeps its country code as
13	 * given; otherwise country code {@code '+61'} is assumed and a single leading {@code '0'} is
14	 * dropped from the national digits. The result must be 8 to 15 digits after the {@code '+'};
15	 * anything else (or any leftover non-digit) is rejected with a 400. So {@code '0412 345 678'} is
16	 * stored as {@code '+61412345678'}.
17	 *
18	 * <p>Known country codes additionally fix the national-number length: {@code '+61'} requires 9
19	 * national digits and {@code '+1'} requires 10. A number whose national part is the wrong length
20	 * for its country code is rejected with a 400. Other country codes carry no length rule.
21	 */
22	public class NormalizeOwnerTelephone {
23	
24	    public void service(@Val OwnerFieldsDto request) throws InvalidTelephoneException {
25	        String raw = request.getTelephone();
26	        request.setTelephone(toE164(raw));
27	    }
28	
29	    private static String toE164(String raw) throws InvalidTelephoneException {
30	        if (raw == null) {
31	            throw new InvalidTelephoneException(raw);
32	        }
33	        String trimmed = raw.trim();
34	        boolean hasCountryCode = trimmed.startsWith("+");
35	        // Strip formatting: spaces, dashes and brackets.
36	        String cleaned = trimmed.replaceAll("[\\s\\-()]", "");
37	
38	        String digits;
39	        if (hasCountryCode) {
40	            digits = cleaned.substring(1); // drop the leading '+', keep the country code
41	        } else {
42	            String national = cleaned;
43	            if (national.startsWith("0")) {
44	                national = national.substring(1); // drop a single leading national-trunk '0'
45	            }
46	            digits = "61" + national; // assume Australian country code
47	        }
48	
49	        if (!digits.matches("\\d{8,15}")) {
50	            throw new InvalidTelephoneException(raw);
51	        }
52	        requireNationalLength(digits, raw);
53	        return "+" + digits;
54	    }
55	
56	    /**
57	     * Enforces the national-number length for country codes that fix it: {@code '61'} requires 9
58	     * national digits, {@code '1'} requires 10. Country codes without a rule pass through.
59	     */
60	    private static void requireNationalLength(String digits, String raw)
61	            throws InvalidTelephoneException {
62	        int required;
63	        int nationalLength;
64	        if (digits.startsWith("61")) {
65	            required = 9;
66	            nationalLength = digits.length() - 2;
67	        } else if (digits.startsWith("1")) {
68	            required = 10;
69	            nationalLength = digits.length() - 1;
70	        } else {
71	            return; // no length rule for this country code
72	        }
73	        if (nationalLength != required) {
74	            throw new InvalidTelephoneException(raw);
75	        }
76	    }
77	}
