264	    public Boolean getPossibleDuplicate() {
265	        return this.possibleDuplicate;
266	    }
267	
268	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
269	        this.possibleDuplicate = possibleDuplicate;
270	    }
271	
272	    public Integer getPossibleDuplicateOf() {
273	        return this.possibleDuplicateOf;
274	    }
275	
276	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
277	        this.possibleDuplicateOf = possibleDuplicateOf;
278	    }
279	
280	    /** Whether this owner has been soft-deleted. A newly created owner is not deleted. */
281	    public Boolean getDeleted() {
282	        return this.deleted;
283	    }
284	
285	    public void setDeleted(Boolean deleted) {
286	        this.deleted = deleted;
287	    }
288	
289	    /**
290	     * The owner's salutation, derived at read time as the {@link #getTitle() title}, a single space
291	     * and the {@link #getLastName() lastName} (e.g. {@code 'DR Franklin'}); just the lastName when no
292	     * title is present.
293	     */
294	    @Transient
295	    public String getSalutation() {
296	        if (this.title == null || this.title.isBlank()) {
297	            return this.getLastName();
298	        }
299	        return this.title + " " + this.getLastName();
300	    }
301	
302	    /**
303	     * The canonical relative URL of this owner, derived at read time as {@code '/api/owners/'}
304	     * followed by the owner's {@link #getId() id}.
305	     */
306	    @Transient
307	    public String getSelfLink() {
308	        return "/api/owners/" + this.getId();
309	    }
310	
311	    /**
312	     * The fiscal year (starting 1 July) containing {@code date}, named by the calendar year it ends
313	     * in: a date on or after 1 July belongs to the next calendar year's fiscal year (e.g. 14 Aug
314	     * 2026 is fiscal year 2027), a date before 1 July to the current calendar year's.
315	     */
316	    public static int fiscalYearOf(LocalDate date) {
317	        return date.getMonthValue() >= 7 ? date.getYear() + 1 : date.getYear();
318	    }
319	
320	    /**
321	     * The owner's fiscal year, derived at read time from the business-day-adjusted
322	     * {@link #getRegistrationDate() registrationDate} and formatted {@code 'FY<YY>'} where YY is the
323	     * last two digits of the fiscal year (which starts on 1 July; e.g. a registration date of
324	     * 14 Aug 2026 yields {@code 'FY27'}). {@code null} when the owner has no registrationDate.
325	     */
326	    @Transient
327	    public String getFiscalYear() {
328	        if (this.registrationDate == null) {
329	            return null;
330	        }
331	        return String.format("FY%02d", fiscalYearOf(this.registrationDate) % 100);
332	    }
333	
334	    /**
335	     * The owner's membership points, derived at read time from stored fields. Starts at 0; add 2 when
336	     * an email is present; add 1 when {@link #getNamesakeCount() namesakeCount} is 0; add 2 for a
337	     * household of 3 or more ({@link #getHouseholdSize() householdSize}); add 3 when tenure — the
338	     * number of elapsed fiscal years since {@link #getRegistrationDate() registrationDate}
339	     * ({@link #getFiscalYear() fiscal year} basis, 1 July start) — is one or more. A newly created
340	     * owner has zero elapsed fiscal years of tenure, so a new owner can score at most 5 points.
341	     */
342	    @Transient
343	    public Integer getMembershipPoints() {
344	        return computeMembershipPoints(this.householdSize);
345	    }
346	
347	    private int computeMembershipPoints(Integer householdSize) {
348	        int points = 0;
349	        boolean hasEmail = this.email != null && !this.email.isBlank();
350	        if (hasEmail) {
351	            points += 2;
352	        }
353	        if (this.namesakeCount != null && this.namesakeCount == 0) {
354	            points += 1;
355	        }
356	        if (householdSize != null && householdSize >= 3) {
357	            points += 2;
358	        }
359	        if (this.registrationDate != null
360	                && fiscalYearOf(LocalDate.now()) - fiscalYearOf(this.registrationDate) >= 1) {
361	            points += 3;
362	        }
363	        return points;
364	    }
365	
366	    /**
367	     * The owner's membership level, a number from 1 to 4 derived at read time by banding
368	     * {@link #getMembershipPoints() membershipPoints}: 1 (0-1 points), 2 (2-3), 3 (4-5), 4 (6 or more).
369	     * Because a new owner scores at most 5 points, only tenure (+3) can reach level 4.
370	     *
371	     * <p>A new owner also cannot outrank their household: when a {@link #getMembershipLevelCap()
372	     * membershipLevelCap} is set (one above the highest level in the household at the moment the owner
373	     * joined) the banded level is capped to it.
374	     */
375	    @Transient
376	    public Integer getMembershipLevel() {
377	        return capLevel(levelForPoints(getMembershipPoints()));
378	    }
379	
380	    /**
381	     * The membership level this owner would band to if their household held {@code householdSize}
382	     * members, still honouring this owner's own {@link #getMembershipLevelCap() cap}. Used when a
383	     * new member sizes their household ceiling against the household as it stands once they join, so
384	     * every existing member is scored under the same (grown) household size.
385	     */
386	    public int membershipLevelForHouseholdSize(int householdSize) {
387	        return capLevel(levelForPoints(computeMembershipPoints(householdSize)));
388	    }
389	
390	    private int capLevel(int level) {
391	        if (this.membershipLevelCap != null && level > this.membershipLevelCap) {
392	            return this.membershipLevelCap;
393	        }
394	        return level;
395	    }
396	
397	    private static int levelForPoints(int points) {
398	        if (points <= 1) {
399	            return 1;
400	        }
401	        if (points <= 3) {
402	            return 2;
403	        }
404	        if (points <= 5) {
405	            return 3;
406	        }
407	        return 4;
408	    }
409	
410	    /**
411	     * The owner's segment, derived at read time and formatted {@code '<TIER>_<AREA>'} — one of
412	     * {@code 'PREMIUM_METRO'}, {@code 'PREMIUM_REGIONAL'}, {@code 'STANDARD_METRO'} or
413	     * {@code 'STANDARD_REGIONAL'}. TIER is {@code 'PREMIUM'} when {@link #getMembershipLevel()
414	     * membershipLevel} is 3 or more, otherwise {@code 'STANDARD'}. AREA is {@code 'METRO'} when the
415	     * {@link #getLocality() locality} is a known region (NSW, VIC or QLD), otherwise
416	     * {@code 'REGIONAL'}.
417	     */
418	    @Transient
419	    public String getOwnerSegment() {
420	        String tier = getMembershipLevel() >= 3 ? "PREMIUM" : "STANDARD";
421	        String area = REGION_TIMEZONE.containsKey(getLocality()) ? "METRO" : "REGIONAL";
422	        return tier + "_" + area;
423	    }
424	
425	    /**
426	     * A single Luhn check digit (0-9) computed at read time over the digits contained in the
427	     * {@link #getCustomerCode() customerCode} (non-digit characters such as the '-' separators are
428	     * ignored). {@code null} when the owner has no customerCode.
429	     */
430	    @Transient
431	    public Integer getCheckDigit() {
432	        if (this.customerCode == null) {
433	            return null;
434	        }
435	        int sum = 0;
436	        boolean dbl = true;
437	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
438	            char c = this.customerCode.charAt(i);
439	            if (c < '0' || c > '9') {
440	                continue;
441	            }
442	            int d = c - '0';
443	            if (dbl) {
444	                d *= 2;
445	                if (d > 9) {
446	                    d -= 9;
447	                }
448	            }
449	            sum += d;
450	            dbl = !dbl;
451	        }
452	        return (10 - (sum % 10)) % 10;
453	    }
454	
455	    /**
456	     * The owner's region, derived at read time. The {@link #getPostcode() postcode} is preferred:
457	     * a 4-digit postcode falling in a known region's range (NSW 2000-2099, VIC 3000-3099,
458	     * QLD 4000-4099) yields that region, which disambiguates cities that share a name. Only when the
459	     * postcode is absent (or in no known range) does it fall back to the fixed city-to-region table
460	     * ({@code Sydney->NSW}, {@code Melbourne->VIC}, {@code Brisbane->QLD}). Any unresolved value
461	     * yields {@code 'UNKNOWN'}.
462	     */
463	    @Transient
464	    public String getLocality() {
465	        String byPostcode = regionForPostcode(this.postcode);
466	        if (byPostcode != null) {
467	            return byPostcode;
468	        }
469	        return CITY_REGION.getOrDefault(this.city, "UNKNOWN");
470	    }
471	
472	    /**
473	     * The owner's IANA timezone, derived at read time from the owner's region
474	     * ({@link #getLocality()}) via the pinned region-to-timezone table (NSW->Australia/Sydney,
475	     * VIC->Australia/Melbourne, QLD->Australia/Brisbane). {@code null} when the region is unknown.
476	     */
477	    @Transient
478	    public String getTimezone() {
479	        return REGION_TIMEZONE.get(getLocality());
480	    }
481	
482	    /** The region whose range contains {@code postcode}, or {@code null} when absent/out of range. */
483	    private static String regionForPostcode(String postcode) {
484	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
485	            return null;
486	        }
487	        int value = Integer.parseInt(postcode);
488	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
489	            int[] range = entry.getValue();
490	            if (value >= range[0] && value <= range[1]) {
491	                return entry.getKey();
492	            }
493	        }
494	        return null;
495	    }
496	
497	    /**
498	     * The stored E.164 {@link #getTelephone() telephone} formatted for humans, derived at read
499	     * time: the country code, a space, then the national digits grouped in threes (e.g.
500	     * {@code '+61412345678'} yields {@code '+61 412 345 678'}). Known country codes ({@code '+61'},
501	     * {@code '+1'}) are split off explicitly; otherwise a two-digit country code is assumed. The
502	     * raw {@link #getTelephone() telephone} itself stays in E.164 form. {@code null} when the owner
503	     * has no telephone or it is not a well-formed E.164 number.
504	     */
505	    @Transient
506	    public String getTelephoneDisplay() {
507	        if (this.telephone == null || !this.telephone.matches("\\+[0-9]+")) {
508	            return null;
509	        }
510	        String digits = this.telephone.substring(1); // drop the leading '+'
511	        String countryCode = countryCodeOf(digits);
512	        String national = digits.substring(countryCode.length());
513	        StringBuilder display = new StringBuilder("+").append(countryCode);
514	        display.append(' ');
515	        for (int i = 0; i < national.length(); i++) {
516	            if (i > 0 && i % 3 == 0) {
517	                display.append(' ');
518	            }
519	            display.append(national.charAt(i));
520	        }
521	        return display.toString();
522	    }
523	
524	    /**
525	     * The E.164 country code at the start of {@code digits} (the '+'-stripped number). Known codes
526	     * are matched longest-first; any other number falls back to a two-digit country code.
527	     */
528	    private static String countryCodeOf(String digits) {
529	        for (String code : KNOWN_COUNTRY_CODES) {
530	            if (digits.startsWith(code) && digits.length() > code.length()) {
531	                return code;
532	            }
533	        }
534	        return digits.length() > 2 ? digits.substring(0, 2) : digits;
535	    }
536	
537	    /** Recognised E.164 country codes, longest-first, for {@link #getTelephoneDisplay()}. */
538	    private static final List<String> KNOWN_COUNTRY_CODES = List.of("61", "1");
539	
540	    /**
541	     * The owner's preferred contact channel, derived at read time: {@code 'EMAIL'} when an
542	     * {@link #getEmail() email} is present, otherwise {@code 'PHONE'}.
543	     */
544	    @Transient
545	    public String getContactPreference() {
546	        boolean hasEmail = this.email != null && !this.email.isBlank();
547	        return hasEmail ? "EMAIL" : "PHONE";
548	    }
549	
550	    /**
551	     * The owner's age band, derived at read time from {@link #getBirthDate() birthDate} measured
552	     * against the {@link #getRegistrationDate() registrationDate}: {@code 'MINOR'} when the owner is
553	     * under 18 at registration, {@code 'ADULT'} from 18 to 64, {@code 'SENIOR'} at 65 or over.
554	     * {@code null} when the owner has no birthDate (or no registrationDate to measure against).
555	     */
556	    @Transient
557	    public String getAgeBand() {
558	        if (this.birthDate == null || this.registrationDate == null) {
559	            return null;
560	        }
561	        int years = java.time.Period.between(this.birthDate, this.registrationDate).getYears();
562	        if (years < 18) {
563	            return "MINOR";
564	        }
565	        if (years < 65) {
566	            return "ADULT";
567	        }
568	        return "SENIOR";
569	    }
570	
571	    /**
572	     * The single derived duplicate-detection key: the 64-character lower-case hex SHA-256 of
573	     * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)} (the normalized
574	     * telephone, the lower-cased email or empty when absent, and the {@link Soundex} of the
575	     * lastName). All duplicate detection is expressed through this one key: a create whose WHOLE
576	     * identityKey equals an existing owner's is a duplicate. Because the telephone is part of the
577	     * key, two members of the same household with different telephones have different identityKeys
578	     * and are both allowed.
579	     */
580	    @Transient
581	    public String getIdentityKey() {
582	        return identityKey(this.telephone, this.email, this.lastName);
583	    }
584	
585	    /**
586	     * Derive the {@link #getIdentityKey() identityKey} from the raw parts, so a create pipeline can
587	     * compute the key for an incoming request exactly as a stored owner reports it.
588	     */
589	    public static String identityKey(String telephone, String email, String lastName) {
590	        String tel = telephone == null ? "" : telephone;
591	        String mail = (email == null || email.isBlank()) ? "" : email.toLowerCase();
592	        return sha256Hex(tel + "|" + mail + "|" + Soundex.encode(lastName));
593	    }
594	
595	    /** The 64-character lower-case hex SHA-256 of {@code seed}. */
596	    private static String sha256Hex(String seed) {
597	        try {
598	            java.security.MessageDigest digest = java.security.MessageDigest.getInstance("SHA-256");
599	            byte[] hash = digest.digest(seed.getBytes(java.nio.charset.StandardCharsets.UTF_8));
600	            StringBuilder hex = new StringBuilder(64);
601	            for (byte b : hash) {
602	                hex.append(String.format("%02x", b & 0xff));
603	            }
604	            return hex.toString();
605	        } catch (java.security.NoSuchAlgorithmException e) {
606	            throw new IllegalStateException("SHA-256 not available", e); // every JRE ships SHA-256
607	        }
608	    }
609	
610	    /** City -> canonical region for {@link #getLocality()}. Any other city is 'UNKNOWN'. */
611	    private static final Map<String, String> CITY_REGION =
612	        Map.of("Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
613	
614	    /** Region -> IANA timezone for {@link #getTimezone()}. */
615	    private static final Map<String, String> REGION_TIMEZONE =
616	        Map.of("NSW", "Australia/Sydney", "VIC", "Australia/Melbourne", "QLD", "Australia/Brisbane");
617	
618	    /** Region -> inclusive 4-digit postcode range {low, high}, preferred by {@link #getLocality()}. */
619	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
620	        "NSW", new int[] {2000, 2099},
621	        "VIC", new int[] {3000, 3099},
622	        "QLD", new int[] {4000, 4099});
623	
624	    protected Set<Pet> getPetsInternal() {
625	        if (this.pets == null) {
626	            this.pets = new HashSet<>();
627	        }
628	        return this.pets;
629	    }
630	
631	    protected void setPetsInternal(Set<Pet> pets) {
632	        this.pets = pets;
633	    }
634	
635	    public List<Pet> getPets() {
636	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
637	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
638	        return Collections.unmodifiableList(sortedPets);
639	    }
640	
641	    public void setPets(List<Pet> pets) {
642	        this.pets = new HashSet<>(pets);
643	    }
644	
645	    public void addPet(Pet pet) {
646	        getPetsInternal().add(pet);
647	        pet.setOwner(this);
648	    }
649	
650	    /**
651	     * Return the Pet with the given name, or null if none found for this Owner.
652	     *
653	     * @param name to test
654	     * @return true if pet name is already in use
655	     */
656	    public Pet getPet(String name) {
657	        return getPet(name, false);
658	    }
659	
660	    /**
661	     * Return the Pet with the given name, or null if none found for this Owner.
662	     *
663	     * @param name to test
664	     * @return true if pet name is already in use
665	     */
666	    public Pet getPet(String name, boolean ignoreNew) {
667	        name = name.toLowerCase();
668	        for (Pet pet : getPetsInternal()) {
669	            if (!ignoreNew || !pet.isNew()) {
670	                String compName = pet.getName();
671	                compName = compName.toLowerCase();
672	                if (compName.equals(name)) {
673	                    return pet;
674	                }
675	            }
676	        }
677	        return null;
678	    }
679	
680	    public Pet getPet(Integer petId) {
681	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
682	    }
683	
684	    @Override
685	    public String toString() {
686	        return new ToStringCreator(this)
687	
688	            .append("id", this.getId())
689	            .append("new", this.isNew())
690	            .append("lastName", this.getLastName())
691	            .append("firstName", this.getFirstName())
692	            .append("address", this.address)
693	            .append("city", this.city)
694	            .append("telephone", this.telephone)
695	            .toString();
696	    }
697	}
