8	import org.slf4j.LoggerFactory;
9	
10	import net.officefloor.plugin.variable.Val;
11	import org.springframework.samples.petclinic.model.Owner;
12	import tools.jackson.databind.ObjectMapper;
13	
14	/**
15	 * Runs in the create-owner pipeline after {@link SaveOwner}, once the owner has been persisted and
16	 * its id assigned. Emits two things on the dedicated {@code AUDIT} logger:
17	 *
18	 * <ol>
19	 * <li>a human-readable audit line recording the new owner's id, {@code customerCode},
20	 * {@code registrationDate} (ISO 'YYYY-MM-DD'), {@code membershipLevel} and {@code membershipNumber};
21	 * and</li>
22	 * <li>an immutable structured event, a JSON object
23	 * {@code {seq, ownerId, customerCode, membershipLevel, event:'OWNER_CREATED'}} where {@code seq} is a
24	 * monotonically increasing integer across every create. The event carries the owner's current
25	 * {@link Owner#getPrimaryIdentifier() primary identifier} — the customerCode today, and whatever
26	 * replaces it later (the memberId once the customerCode is unified into it) — so downstream consumers
27	 * always see the owner's live external handle without this step changing.</li>
28	 * </ol>
29	 *
30	 * Read-only: it inspects the stored owner without mutating it, then hands off to the responder.
31	 */
32	public class AuditOwnerCreated {
33	
34	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
35	
36	    /** Monotonically increasing sequence number across every create, process-wide. */
